import { Component, Element, Prop, Watch, h } from "@stencil/core";

/**
 * @since 1.2.2
 * @status stable
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-divider",
	styleUrl: "divider.scss",
	shadow: true,
})
export class Divider {
	/** Draws the divider in a vertical orientation */
	@Prop({ reflect: true }) vertical = false;

	/** Removes spacing around the divider */
	@Prop({ reflect: true }) noPadding = false;

	/** Adjust this to get dark to light border color for the divider */
	@Prop({ reflect: true }) prominence: "strong" | "medium" | "weak" = "weak";

	/** Adjust this prop to get thin to thick divider */
	@Prop({ reflect: true }) size: "small" | "medium" = "small";

	/** Adjust this prop to make the divider spill out the parent (no position styles) and fill to its grandparent's (position: relative) length */
	@Prop({ reflect: true }) grow = false;

	@Element() private host: HTMLHbrDividerElement;

	@Watch("vertical")
	handleVerticalChange() {
		this.host.setAttribute(
			"aria-orientation",
			this.vertical ? "vertical" : "horizontal",
		);
	}

	connectedCallback() {
		this.host.setAttribute(
			"aria-orientation",
			this.vertical ? "vertical" : "horizontal",
		);
	}

	render() {
		return (
			<div
				part="base"
				class={{
					divider: true,
					"divider--vertical": this.vertical,
					"divider--noPadding": this.noPadding,
					[`divider--prominence-${this.prominence}`]: true,
					[`divider--size-${this.size}`]: true,
					"divider--grow": this.grow,
				}}
				// biome-ignore lint/a11y/useAriaPropsForRole: <explanation>
				role="separator"
			/>
		);
	}
}
